entries[390614] = { ["name"] = "Frostbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt das Ziel mit einer 'Frostbombe'. Die Bombe explodiert nach 5 Sek., fügt dem Ziel (931% der Zaubermacht) Frostschaden und allen anderen Gegnern innerhalb von 10 Metern (465.696% der Zaubermacht) Frostschaden zu. Alle betroffenen Ziele werden 4 Sek. lang um 70% verlangsamt.\n\nWenn 'Frostbombe' vor der Explosion gebannt wird, erhaltet Ihr eine Aufladung von 'Hirnfrost'." }
entries[390615] = { ["name"] = "Licht aus der Dunkelheit", ["text"] = "Disziplin, Schatten\nJedes Mal, wenn 'Schattenwort: Schmerz' Schaden verursacht, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 3% erhöht, bis zu einem Maximum von [60][60]%.\n\nHeilig\nJedes Mal, wenn 'Schattenwort: Schmerz' oder 'Heiliges Feuer' Schaden verursacht, wird die Heilung Eures nächsten Einsatzes von 'Blitzheilung' um 3% erhöht, bis zu einem Maximum von [60][60]%." }
