entries[390710] = { ["name"] = "Zorn des Großstabs", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht den durch den Großstab der Bruthüterin verursachten Schaden um 10%.Dieser Effekt ist stapelbar.\n\nSpielercharaktere können in der Nähe der aufgestellten Waffe ' Fokusgroßstab ' einsetzen, was eine Aufladung von 'Zorn des Großstabs' verbraucht und bewirkt, dass ein Strahl den Spielercharakter verfolgt.\n\nDer konzentrierte Strahl fügt während der Verfolgung Spielercharakteren innerhalb von 3 Metern alle 0,5 Sek. 123660 Naturschaden zu und zerstört Eier in seiner Bahn. Wenn ein Ei zerstört wird, löst dies 'Wut der Gelegehüterin' aus." }
entries[390711] = { ["name"] = "Zorn des ermächtigten Großstabs", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht den durch den ermächtigten Großstab der Bruthüterin verursachten Schaden um 30%.Dieser Effekt ist stapelbar und beginnt mit 2 Aufladungen.\n\nDiurna ermächtigt die aufgestellte Waffe, ruft ihren Zorn hervor und verbraucht eine Aufladung von 'Zorn des ermächtigten Großstabs' für jeden anvisierten Spielercharakter und bewirkt, dass ein Strahl den Spielercharakter verfolgt.\n\nDer konzentrierte Strahl fügt während der Verfolgung Spielercharakteren innerhalb von 3 Metern alle 0,5 Sek. 141326 Naturschaden zu und zerstört Eier in seiner Bahn. Wenn ein Ei zerstört wird, löst dies 'Wut der Gelegehüterin' aus." }
entries[390713] = { ["name"] = "Totentanz", ["text"] = "Furor, Schutz\nWenn ein Gegner stirbt während er von Eurem 'Verheerer' beeinträchtigt ist, wird die Dauer um 2 Sek. verlängert.\n\nDieser Effekt kann höchstens 3-mal pro Einsatz von 'Verheerer' auftreten.\n\nWaffen\nWenn ein Gegner stirbt, während Euer 'Klingensturm' aktiv ist, wird jeglicher durch Euch verursachte Schaden für die Restdauer von 'Klingensturm' und 2 Sek. danach um 5% erhöht.\n\nWenn ein Gegner stirbt während er von Eurem 'Verheerer' beeinträchtigt ist, wird die Dauer um 2 Sek. verlängert.\n\nDiese Effekte können höchstens 3-mal pro Einsatz von 'Klingensturm' oder 'Verheerer' auftreten." }
