entries[391425] = { ["name"] = "Eisiges Sturmgewitter", ["text"] = "Unbegrenzte Reichweite\nWirken in 2.5 sek.\nDie Luft verwandelt sich in Eis, die Temperatur fällt drastisch und führt dazu, dass Spielercharaktere sich innerhalb von 10 Metern zu mindestens 2 anderen Spielercharakteren aufhalten müssen, wenn sie nicht mit ' Zu Eis erstarrt ' belegt werden wollen." }
entries[391426] = { ["name"] = "Ozeanwelle", ["text"] = "1000 Meter Reichweite\nSofort\nFügt einem Gegner 75 Naturschaden zu.\n\nVerringert die Bewegungsgeschwindigkeit des Ziels 5 Sek. lang um 30%.\n\nStößt einen Gegner zurück." }
entries[391427] = { ["name"] = "Kesseldämpfe" }
entries[391428] = { ["name"] = "Toxin" }
entries[391429] = { ["name"] = "Futter für die Flamme", ["text"] = "'Geistersicht' hat eine um 30 Sek. erhöhte Abklingzeit und macht einen verurteilten Dämon 25 Sek. lang sichtbar. [ Rachsucht : 'Dämonische Verwüstung' /\n\nVerwüstung\n'Augenstrahl' ] und 'Gleve werfen' fügen dem Dämon tödlichen Schaden zu und gewähren 15 Sek. lang 20% mehr Schaden.\n\nBeim Tod explodiert der Dämon, fügt Gegnern in der Nähe (192.5% der Angriffskraft) Schatten schaden zu und heilt Euch um 20% Eurer maximalen Gesundheit. Die Explosion fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[391430] = { ["name"] = "Futter für die Flamme", ["text"] = "Sofort 2 min Abklingzeit\nEure Schaden verursachenden Fähigkeiten haben eine Chance, für 25 Sek. einen Dämon aus dem Theater der Schmerzen herbeizurufen. 'Gleve werfen' fügt dem Dämon tödlichen Schaden zu. Beim Tod explodiert er, fügt Gegnern in der Nähe (192.5% der Angriffskraft) Schatten schaden zu und heilt Euch um 20% Eurer maximalen Gesundheit. Die Explosion fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[391431] = { ["name"] = "Windgepeitschte Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nKräuter, die in hoch gelegenen oder besonders windigen Regionen wie den Ebenen von Ohn'ahra wachsen, können die elementare Macht der Luft absorbieren. Wenn diese Kräuter gesammelt werden, werden mächtige Windböen entfesselt, die Sammelnde wegstoßen. Es ist allerdings eine effektive Methode, um tobende Luft zu erhalten.\n\nKräuterkundige mit Spezialisierung in windgepeitschten Kräutern erhalten beim Sammeln folgenden Effekt:\n\nWindgepeitscht :\nWenn Ihr tiefer als 40 Meter fallt, wird eine mächtige Windböe Euren Fall verlangsamen." }
entries[391441] = { ["name"] = "Steinbrich", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nSteinbrich ist ein widerstandsfähiges Kraut, das an zahlreichen Orten gedeihen kann. Obwohl es allgemein an felsigen Standorten wie Gebirgen oder Klippen auffindbar ist, wächst es auch auf weiten Ebenen oder vereinzelt in vulkanischen Gebieten." }
entries[391444] = { ["name"] = "Blasenmohn", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nBlasenmohn ist ein empfindliches Kraut, das an feuchten Orten auf den Dracheninseln wächst. Es wächst entlang der Flüsse, Küsten und in feuchten Höhlen.\n\nDie Blasenmohnblume mag einzigartig aussehen, ist aber nicht zu viel zu gebrauchen. Die wässrige Pilzkugel, die sich am Stiel bildet, ist der wertvolle Teil." }
entries[391445] = { ["name"] = "Zorn der See", ["text"] = "1000 Meter Reichweite\nSofort\nFügt einem Gegner 75 Naturschaden zu.\n\nVerringert die Bewegungsgeschwindigkeit des Ziels 5 Sek. lang um 30%.\n\nStößt einen Gegner zurück." }
entries[391446] = { ["name"] = "Zu Eis erstarrt", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Kälte macht den Spielercharakter handlungsunfähig und fügt ihm alle 1 Sek. 52997 Frostschaden zu. Hält 10 Sek. lang an. Dieser Effekt kann nicht mitigiert oder vermieden werden." }
entries[391447] = { ["name"] = "Krümmrinde", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKrümmrinde ist ein grünliches Kraut, das auf den Dracheninseln gefunden werden kann. Es wächst dort, wo es reichlich Bäume oder Grünpflanzen gibt." }
entries[391449] = { ["name"] = "Zorn der See", ["text"] = "Kanalisiert (Wirken in 32 sek.)\nBeschwört Meerwasserwellen, die 75 Naturschaden verursachen und das Ziel um 30% verlangsamen." }
entries[391450] = { ["name"] = "Dunkle Leere", ["text"] = "Sofort\nLöst eine Explosion aus dunkler Energie um Euer Ziel herum aus, die Eurem Ziel und 15 Gegnern in der Nähe (74.8% der Zaubermacht) Schattenschaden zufügt und sie mit 'Schattenwort: Schmerz' belegt.\n\nErzeugt 15 Wahnsinn." }
entries[391451] = { ["name"] = "Beschworene Karte" }
entries[391452] = { ["name"] = "Drachenschlag" }
entries[391453] = { ["name"] = "Gaumenreiniger", ["text"] = "Sofort\nReinigt gründlich Euren Verstand, Körper und Geist von... was immer DAS auch war." }
entries[391454] = { ["name"] = "Drachenschlag", ["text"] = "300 Meter Reichweite\nSofort\nFügt getroffenen Zielen Naturschaden zu." }
entries[391457] = { ["name"] = "Lavaermächtigung", ["text"] = "Sofort\nMagmahauer wird in der Lava gestärkt, was sämtlichen verursachten Schaden um 25% erhöht." }
entries[391458] = { ["name"] = "Blutroter Boden", ["text"] = "Während Ihr Euch im Effektbereich Eurer Fähigkeit 'Tod und Verfall' befindet, ist Euer verursachter Schaden um 6% sowie Eure erhaltene Heilung um 5% erhöht." }
entries[391459] = { ["name"] = "Blutroter Boden", ["text"] = "Sofort\nWährend Ihr Euch im Effektbereich Eurer Fähigkeit 'Tod und Verfall' befindet, ist Euer verursachter Schaden um 6% sowie Eure erhaltene Heilung um 5% erhöht." }
entries[391460] = { ["name"] = "Eisige Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nWenn diese Kräuter kälterem Klima ausgesetzt werden oder in der Nähe von Wasserquellen wachsen, können sie mit Elementarfrost erfüllt werden. Beim Sammeln dieser Kräuter wird der Boden von rutschigem Eis bedeckt, doch Kräuterkundige werden für ihre Mühen mit tobendem Frost belohnt.\n\nKräuterkundige mit Spezialisierung in eisigen Kräutern erhalten beim Sammeln folgenden Effekt:\n\nEisige Blütenblätter :\nHüllt Euch in eine Frostwolke ein, die jeden Gegner, der Euch zu nahe kommt, vorübergehend einfriert." }
entries[391461] = { ["name"] = "Leicht eisiger Kristall" }
entries[391463] = { ["name"] = "Mit Verfall bedeckt", ["text"] = "Sofort\nIhr seid leicht erkrankt, aber auf dem Pfad der Genesung! Die Bewegungsgeschwindigkeit und sämtliche Werte sind verringert, aber nur geringfügig." }
entries[391470] = { ["name"] = "Zertrümmernder Schlag", ["text"] = "10 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nFügt einem Gegner 125 Feuerschaden zu und entfernt 20 nützliche Magieeffekte." }
entries[391471] = { ["name"] = "Reinigende Sporen", ["text"] = "Sofort\nUmhüllt Spielercharaktere innerhalb von 40 Metern mit einer Wolke reinigender Sporen. Heilt 30 Min. lang alle 15 Sek eine Anwendung eines Gift- oder Krankheitseffekts." }
entries[391472] = { ["name"] = "Streicheln", ["text"] = "3 Meter Reichweite\nWirken in 1.5 sek.\nStreichelt eine niedliche Kreatur!" }
entries[391473] = { ["name"] = "Tavios Herstellung von Angelausrüstung", ["text"] = "Sofort\nTavio wird für Euch Angelausrüstung und Aufwertungen herstellen." }
entries[391476] = { ["name"] = "Magmapfütze" }
entries[391477] = { ["name"] = "Koagulophathie", ["text"] = "Von 'Blutseuche' betroffene Gegner erleiden durch Euch 5% mehr Schaden, und 'Todesstoß' erhöht den Schaden Eurer 'Blutseuche' 12 Sek. lang um 25%. Dieser Effekt ist bis zu 5-mal stapelbar." }
entries[391479] = { ["name"] = "Flammendes Inferno" }
entries[391481] = { ["name"] = "Koagulophathie", ["text"] = "100 Meter Reichweite\nSofort\nVon 'Blutseuche' betroffene Gegner erleiden durch Euch 5% mehr Schaden, und 'Todesstoß' erhöht den Schaden Eurer 'Blutseuche' 12 Sek. lang um 25%. Dieser Effekt ist bis zu 5-mal stapelbar." }
entries[391482] = { ["name"] = "Obsidian einatmen" }
entries[391488] = { ["name"] = "Reaktiver Staub" }
entries[391489] = { ["name"] = "Obsidian Inhale Trigger" }
entries[391491] = { ["name"] = "Unverwüstliches Schmettern", ["text"] = "12 Meter Reichweite\nWirken in 2.5 sek.\nFügt Gegnern in einem 15 Meter großen kegelförmigen Bereich 20 körperlichen Schaden zu und verlangsamt sie 10 Sek. lang um 25%." }
entries[391492] = { ["name"] = "Verrottete Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nKräuter, die der Essenz des Verfalls ausgesetzt sind, verkommen zu welken Versionen ihrer selbst. Die Pflanzen sind nach wie vor verwendbar, doch wer auch immer sie sammelt, wird ebenfalls dem Verfall ausgesetzt und von Krankheit befallen. Es kann sich jedoch lohnen, da diese Kräuter eine zuverlässige Quelle für tobenden Verfall sind.\n\nKräuterkundige mit Spezialisierung in verfallenen Kräutern erhalten beim Sammeln folgenden Effekt:\n\nKontrollierter Verfall :\nErmächtigt durch vorhandene Verfallmagie. Euer Zauber ' Elementarkraut überladen ' lädt sich mit 400% der normalen Rate auf." }
entries[391493] = { ["name"] = "Glühendes Erz", ["text"] = "Sofort\nVon einer Ader geschmolzenen Erzes in Brand gesteckt. Erleidet im Verlauf von 20 Sek. regelmäßig Feuerschaden. Kann durch Abtauchen in Wasser vorzeitig beendet werden." }
entries[391496] = { ["name"] = "Titanenberührte Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nKräuter, die in Gebieten wachsen, in denen der Einfluss der Titanen stark verbreitet ist, wie beispielsweise der Küste des Erwachens oder Thaldraszus, können auf ähnliche Weise ermächtigt werden. Diese Art Kräuter verleihen Kräuterkundigen, die diese finden, einen Segen sowie tobende Ordnung.\n\nKräuterkundige mit Spezialisierung in titanenberührten Kräutern erhalten beim Sammeln folgenden Effekt:\n\nErleuchtetes Potenzial :\nErhöht die Geschwindigkeit um 15%. Außerdem werden die Sekundärwerte von auf titanenberührte Vorkommen spezialisierten Sammlern um 3% erhöht." }
entries[391497] = { ["name"] = "Welpenexplosion" }
entries[391498] = { ["name"] = "Wutentbrannte Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nWird nur in Gegenden gefunden, in denen ein Konflikt herrscht. Diese Kräuter sollen durch den Zorn jener, die in ihrer Umgebung kämpfen, angeblich magische Eigenschaften erhalten haben.\n\nGewährt beim Sammeln folgenden Effekt:\n\nFuror des Kampfes :\nWenn Ihr gegnerische Spielercharaktere tötet, habt Ihr eine Chance, tobende Zorneskraft zu erhalten. Hält 2 Min. lang an.\n\nWeiteres Abbauen oder Kräutersammeln verlängert die Dauer." }
