entries[391557] = { ["name"] = "Titanenberührtes Kraut überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Kräutern dieser Art bewirkt, dass sich ein Portal zu weiteren Kräutern in der Nähe öffnet. Spezialisierte Kräuterkundige können nach getaner Arbeit am Zielort ein Rückkehrportal öffnen." }
entries[391558] = { ["name"] = "Wutentbranntes Kraut überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Kräutern dieser Art verursacht eine verheerende Schockwelle, die Gegner in der Nähe zurückstößt und Euch selbst stärkt." }
entries[391559] = { ["name"] = "Schnellende Schüsse", ["text"] = "'Schnellfeuer' verursacht 35% mehr Schaden und 'Gezielter Schuss' hat eine Chance von 15%, die Abklingzeit von 'Schnellfeuer' abzuschließen.\n(Procchance: 15%)" }
entries[391560] = { ["name"] = "Windgepeitschtes Kraut überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Kräutern dieser Art verursacht eine massive Windböe, die Euch schnell in die Luft schleudert und es Euch ermöglicht, langsam zu Boden zu gleiten, während Ihr Kräuter und tobende Luft sammelt." }
entries[391561] = { ["name"] = "Schnellende Schüsse" }
entries[391562] = { ["name"] = "Eisiges Kraut überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von Kräutern dieser Art offenbart einen Eisblock, in dem Kräuter eingeschlossen sind. Wird dieser Eisblock angegriffen, lösen sich Brocken ab, über die gelaufen werden kann, um Kräuter und tobender Frost zu erhalten." }
entries[391564] = { ["name"] = "Verfallenes Kraut überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von verfallenen Kräutern beschwört eine siechende Krümmrinde herauf, eine Kreatur, die von Verfall betroffen ist. Das Bezwingen dieser Kreatur gewährt Kräuter und tobender Verfall." }
