entries[391570] = { ["name"] = "Reaktiver Staub", ["text"] = "Unbegrenzte Reichweite\nSofort\n' Erfüllter Niederschlag ' regnet von der Decke und erfüllt alle Spielercharaktere mit schädlicher irdener Energie.\n\nVerursacht alle 5.2 Sek. 45 Naturschaden.\n\nDie Energie von ' Erfüllter Niederschlag ' wird bei Kontakt vom Effekt ' Erweckte Erde ' aufgenommen, wodurch er entfernt wird.\n\nWenn zwei Spielercharaktere, die unter dem Einfluss von ' Erfüllter Niederschlag ' stehen, in Kontakt miteinander geraten, wird eine 'Explosive Reaktion' ausgelöst." }
