entries[391589] = { ["name"] = "Kohlebefeuerte Rippchen", ["text"] = "Sofort\nDie Garung über einem Bett aus Ankerkraut, Sirenenpollen und frischen Vorquinkohlen erzeugt einen deftigen Geschmack, der Euch ein durchdringendes Erlebnis bietet! Erhöht die Ausdauer 1 Stunde lang um 20%.\n\nNur auf den Dracheninseln aktiv." }
entries[391590] = { ["name"] = "Rauchiger Portwein", ["text"] = "Sofort\nEin loagesegneter Krug rauchigen Portweins, mit dem Ihr Euer fleischhaltiges Mahl runterspülen könnt. Erhöht die Hauptwert 1 Stunde lang um 10%.\n\nNur auf den Dracheninseln aktiv." }
