entries[391599] = { ["name"] = "Urzeitlicher Blizzard", ["text"] = "300 Meter Reichweite\nSofort\nBei 100 Energie kanalisiert Kadros einen eiskalten Sturm für 10 Sek., der jedem Spielercharakter innerhalb von 3 Metern alle 1 Sek. 8 Frostschaden zufügt. Außerdem wird für 15 Sek. der erlittene Frostschaden um 10% erhöht, während Feuerschaden um 10% verringert wird. ' Verbrannter Boden ' hebt diesen Effekt auf.\n\nBei 10 Stapeln werden Spielercharaktere in einem ' Frostgrab ' gefangen." }
