entries[391603] = { ["name"] = "Aruunembeerentörtchen", ["text"] = "Sofort\nEin Törtchen mit Wildbeeren, die entlang der Orunaiküste wachsen. Stark genug, um die Kälte fernzuhalten! Verringert den erlittenen Frostschaden 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv." }
