entries[391619] = { ["name"] = "Drachenfruchtpunsch", ["text"] = "Sofort\nLehnt Euch zurück und genießt eine Tasse mit den besten Früchten und Beeren der Dracheninseln auf dieser Seite der Kaskaden. Verringert die Fallgeschwindigkeit.\n\nNur auf den Dracheninseln aktiv." }
entries[391620] = { ["name"] = "Poschierter azsunianscher Hummer", ["text"] = "Sofort\nKräftiger Nor'danilhummer, nach traditioneller Art der Verheerten Inseln pochiert und eingelegt. Erhöht alle Werte 1 Stunde lang um 5%.\n\nNur auf den Dracheninseln aktiv." }
entries[391621] = { ["name"] = "Uralte Giftwolke", ["text"] = "100 Meter Reichweite\nSofort 5 min Abklingzeit\nVergiftet alle Gegner innerhalb von 8 Metern um den Zaubernden. Die Opfer des Giftes erleiden 45 Sek. lang alle 5 Sek. 1480 Naturschaden.\nGegner, die während der Vergiftung sterben, setzen eine Welle der Heilung frei, die Verbündete in der Nähe um 16652 Gesundheit heilt." }
entries[391622] = { ["name"] = "Verwandlung", ["text"] = "4% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerwandelt den Gegner in eine Ente, die 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]" }
