entries[391806] = { ["name"] = "Szepter des Spektakels: Luft", ["text"] = "Wirken in 2 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub , Tobende Luft (3), Krümmrinde\nBerufsausbilder:\nVerzauberkunst der Dracheninseln (20)\nKosten:\n75\n\nSzepter des Spektakels: Luft\nWaffenhand\n1 Schaden Geschwindigkeit 1.60\n(0.6 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nBenutzen: Schwenkt das Szepter und projiziert eine illusorische Luftkugel vor Euch.\n50 Aufladungen" }
