entries[391888] = { ["name"] = "Adaptiver Schwarm", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort 25 sek. Abklingzeit\nBefehligt einen Schwarm, der im Verlauf von 12 Sek. ein Ziel um (157.5% der Zaubermacht) Gesundheit heilt oder ihm (264% der Zaubermacht) Naturschaden zufügt und die Effektivität Eurer regelmäßigen Effekte beim Ziel um 25% erhöht.\n\nBei Ablauf sucht sich der Schwarm bis zu 3-mal ein neues Ziel, wobei er versucht, abwechselnd zwischen einem Verbündeten und einem Gegner überzuspringen." }
entries[391889] = { ["name"] = "Adaptiver Schwarm", ["text"] = "100 Meter Reichweite\nSofort\nWiederherstellung ( Wiederherstellungsdruide )\nBefehligt einen Schwarm, der im Verlauf von 12 Sek. ein Ziel um (157.5% der Zaubermacht) Gesundheit heilt oder ihm (264% der Zaubermacht) Naturschaden zufügt und die Effektivität Eurer regelmäßigen Effekte beim Ziel um 20% erhöht.\n\nBei Ablauf sucht sich der Schwarm bis zu 3-mal ein neues Ziel, wobei er versucht, abwechselnd zwischen einem Verbündeten und einem Gegner überzuspringen.\n\nGleichgewicht, Wildheit, Wächter\nBefehligt einen Schwarm, der im Verlauf von 12 Sek. ein Ziel um (157.5% der Zaubermacht) Gesundheit heilt oder ihm (264% der Zaubermacht) Naturschaden zufügt und die Effektivität Eurer regelmäßigen Effekte beim Ziel um 25% erhöht.\n\nBei Ablauf sucht sich der Schwarm bis zu 3-mal ein neues Ziel, wobei er versucht, abwechselnd zwischen einem Verbündeten und einem Gegner überzuspringen." }
